const [flag, format] = process.argv.slice(2);

if (flag !== '--format' || !['text', 'json', 'csv'].includes(format)) {
  console.error('Usage: node src/report.js --format <text|json|csv>');
  process.exitCode = 1;
} else {
  console.log(format === 'json' ? JSON.stringify('ok') : 'ok');
}

